// A limit's shape, short: "64 GB+ NVMe".
const shapeOf = (r) => num(r.min_ram_gb) + ' GB+' + (String(r.nvme_required) === 'true' ? ' NVMe' : '');
const chart = context.panel.chart;
const CW = chart && typeof chart.getWidth === 'function' ? chart.getWidth() : 0;
const CH = chart && typeof chart.getHeight === 'function' ? chart.getHeight() : 0;
const empty = (text) => ({ backgroundColor: 'transparent', title: { text, left: 'center', top: 'middle',
  textStyle: { color: '#8D99AB', fontSize: 13, fontWeight: 'normal' } } });
const missing = (name) => empty('the view ' + name + ' did not answer');
const TIP = { backgroundColor: '#10151C', borderColor: '#1F2733', textStyle: { color: '#E7ECF3', fontSize: 12 } };
const AXIS_LABEL = { color: '#8D99AB', fontFamily: MONO, fontSize: 10, hideOverlap: true };
const timeAxis = (extra) => Object.assign({ type: 'time', min: Math.floor(from / DAY) * DAY, max: to,
  axisLine: { lineStyle: { color: '#1F2733' } }, axisTick: { show: false }, splitLine: { show: false },
  axisLabel: Object.assign({ formatter: (t) => dayLabel(t) }, AXIS_LABEL) }, extra || {});
const valueAxis = (extra) => Object.assign({ type: 'value', min: 0, splitNumber: 4,
  splitLine: { lineStyle: { color: '#1F2733' } }, axisLabel: AXIS_LABEL }, extra || {});
// A plain legend wraps where a scroll legend would page and hide series: the grid starts below its last line.
const legendTop = (names) => {
  let rows = 1, line = 0;
  names.forEach((n) => {
    const w = 13 + n.length * 7.4;
    if (CW && line && line + 16 + w > CW) { rows += 1; line = w; } else line += (line ? 16 : 0) + w;
  });
  return 34 + (rows - 1) * 22;
};
const LEGEND = { type: 'plain', top: 0, left: 0, right: 0, icon: 'circle', itemWidth: 8, itemHeight: 8, itemGap: 16,
  textStyle: { color: '#C9D2DE', fontFamily: MONO, fontSize: 12 } };

if (!view.flow_daily) return missing('flow-daily');
const rows = inRange(view.flow_daily);
if (!rows.length) return empty('no offers in ' + span);
const at = (col) => rows.map((r) => [dayOf(r.day), num(r[col])]);
const SERIES = [['appeared', 'bar', '#60A5FA'], ['gone', 'bar', '#C4B5FD'], ['live at the end of the day', 'line', '#7DD3FC']];
const cols = { appeared: 'appeared', gone: 'gone', 'live at the end of the day': 'live_at_end_of_day' };
return {
  backgroundColor: 'transparent', animation: false,
  legend: LEGEND,
  grid: { left: 44, right: 16, top: legendTop(SERIES.map((s) => s[0])), bottom: 28 },
  tooltip: Object.assign({ trigger: 'axis', axisPointer: { type: 'line', lineStyle: { color: '#1F2733' } },
    formatter: (ps) => dayLabel(ps[0].value[0]) + '<br/>' + ps.filter((p) => p.value[1] !== null)
      .map((p) => p.marker + p.seriesName + ' ' + count(p.value[1])).join('<br/>') }, TIP),
  xAxis: timeAxis(),
  yAxis: valueAxis({ minInterval: 1 }),
  series: SERIES.map(([name, type, colour]) => Object.assign({ name, type, data: at(cols[name]), itemStyle: { color: colour } },
    type === 'bar' ? { barMaxWidth: 6, barGap: '10%' } : { showSymbol: false, connectNulls: false, lineStyle: { width: 1.5, color: colour } })),
};
